// Plan de subredes de la VPC 172.20.0.0/16: dos zonas, tres capas en cada una.
export const plan = {
  vpc: "172.20.0.0/16",
  subnets: [
    { name: "web-a", cidr: "172.20.0.0/26" },
    { name: "web-b", cidr: "172.20.0.64/26" },
    { name: "app-a", cidr: "172.20.1.0/25" },
    { name: "app-b", cidr: "172.20.1.128/25" },
    { name: "datos-a", cidr: "172.20.4.0/22" },
    { name: "datos-b", cidr: "172.21.4.0/22" },
  ],
};

spec.code:
const subred = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
const minimos: { name: string; usable: number }[] = [
  { name: "web-a", usable: 60 },
  { name: "web-b", usable: 60 },
  { name: "app-a", usable: 250 },
  { name: "app-b", usable: 250 },
  { name: "datos-a", usable: 1000 },
  { name: "datos-b", usable: 1000 },
];
for (const { name, usable } of minimos) {
  const hay = aws.cidr.usableAddresses(subred(name).cidr);
  assert.ok(hay >= usable, name + " ofrece " + hay + " direcciones utilizables y se piden " + usable);
}

for (const { name, cidr } of plan.subnets) {
  assert.ok(aws.cidr.contains("172.20.0.0/17", cidr), name + " (" + cidr + ") queda fuera de la mitad inferior de la VPC");
}

const subred = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
const maximos: { name: string; usable: number }[] = [
  { name: "web-a", usable: 123 },
  { name: "web-b", usable: 123 },
  { name: "app-a", usable: 251 },
  { name: "app-b", usable: 251 },
  { name: "datos-a", usable: 1019 },
  { name: "datos-b", usable: 1019 },
];
for (const { name, usable } of maximos) {
  assert.ok(aws.cidr.usableAddresses(subred(name).cidr) <= usable, name + " es más grande de lo necesario");
}

