// Dimensionamiento de una subred para 14 instancias, redactado por un asistente.
export const subred = {
  cidr: "10.0.0.16/28",
  recursos: 14,
  direccionesUtilizables: 16,
};

solution.code:
export const subred = {
  cidr: "10.0.0.0/27",
  recursos: 14,
  direccionesUtilizables: 27,
};

spec.code:
const partes = subred.cidr.split("/");
const prefijo = Number(partes[1] ?? "32");
const total = 2 ** (32 - prefijo);
assert.strictEqual(subred.direccionesUtilizables, total - 5, "La subred " + subred.cidr + " reúne " + total + " direcciones y reserva cinco");

const partes = subred.cidr.split("/");
const direccion = partes[0] ?? "";
const prefijo = Number(partes[1] ?? "32");
const valor = direccion.split(".").reduce((total: number, trozo: string) => total * 256 + Number(trozo), 0);
assert.strictEqual(valor % 2 ** (32 - prefijo), 0, subred.cidr + " no empieza en una dirección de red");
